import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col } from "reactstrap";
import "../Styles/UserRegister.css";
import { Link, useNavigate } from "react-router-dom";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { UsersSchemaValidation } from "../Validations/UserSchemaValidation";

const MAJORS = [
  "",
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const UserRegister = () => {
  const navigate = useNavigate();
  const [role, setRole] = useState("student");

  // ✅ إعداد react-hook-form مع yup
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(UsersSchemaValidation),
  });

  // ✅ عند الإرسال
  const onSubmit = (data) => {
    const payload = { ...data, role };
    localStorage.setItem("userData", JSON.stringify(payload));
    alert("Student Registered ✅");
    navigate("/profile");
  };

  // ✅ التبديل بين Student / Company
  const handleRoleSwitch = (newRole) => {
    setRole(newRole);
    if (newRole === "company") {
      navigate("/company-register");
    }
  };

  return (
    <div className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>

      {/* Role Switch */}
      <div className="role-switch">
        <button
          type="button"
          className={role === "student" ? "role-btn active" : "role-btn"}
          onClick={() => handleRoleSwitch("student")}
        >
          Student
        </button>

        <button
          type="button"
          className={role === "company" ? "role-btn active" : "role-btn"}
          onClick={() => handleRoleSwitch("company")}
        >
          Company
        </button>
      </div>

      {/* Registration Form */}
      <div className="reg-card">
        <p className="reg-sub">Please fill in your details to continue</p>

        <Form onSubmit={handleSubmit(onSubmit)}>
          <FormGroup>
            <Label>Full Name</Label>
            <Input
              type="text"
              placeholder="Your name"
              {...register("fullName")}
            />
            {errors.fullName && (
              <p className="error">{errors.fullName.message}</p>
            )}
          </FormGroup>

          <FormGroup>
            <Label>Email</Label>
            <Input
              type="email"
              placeholder="you@example.com"
              {...register("email")}
            />
            {errors.email && <p className="error">{errors.email.message}</p>}
          </FormGroup>

          <FormGroup>
            <Label>Password</Label>
            <Input
              type="password"
              placeholder="********"
              {...register("password")}
            />
            {errors.password && (
              <p className="error">{errors.password.message}</p>
            )}
          </FormGroup>

          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Major</Label>
                <Input type="select" {...register("major")}>
                  {MAJORS.map((m, index) => (
                    <option key={index} value={m}>
                      {m === "" ? "Select your major" : m}
                    </option>
                  ))}
                </Input>
                {errors.major && (
                  <p className="error">{errors.major.message}</p>
                )}
              </FormGroup>
            </Col>

            <Col md={6}>
              <FormGroup>
                <Label>Age</Label>
                <Input type="number" min="17" max="45" {...register("age")} />
                {errors.age && <p className="error">{errors.age.message}</p>}
              </FormGroup>
            </Col>
          </Row>

          <button type="submit" className="reg-btn">
            Sign up
          </button>

          <p className="login-text">
            Already have an account?{" "}
            <Link to="/login" className="login-link">
              Log in now!
            </Link>
          </p>
        </Form>
      </div>
    </div>
  );
};

export default UserRegister;
